function piBookingBlockedHint() {
  return 'Booking.com blocked this sign-in (Try again later). This is not a wrong password — Booking.com blocked this server network. Do not retry now; waiting a minute makes it worse. Leave Collect closed for several hours.';
}
let _piBookingConnectBlockedUntil = 0;
const PI_BOOKING_BLOCK_FILE = '/tmp/elysian-booking-connect-blocked-until';
function piBookingCooldownMs() {
  const n = Number(process.env.BOOKING_CONNECT_COOLDOWN_MS);
  return Number.isFinite(n) && n >= 0 ? n : (4 * 60 * 60 * 1000);
}
function piBookingReadBlockedUntil() {
  if (_piBookingConnectBlockedUntil > Date.now()) return _piBookingConnectBlockedUntil;
  try {
    const n = Number(require('fs').readFileSync(PI_BOOKING_BLOCK_FILE, 'utf8'));
    if (Number.isFinite(n) && n > Date.now()) {
      _piBookingConnectBlockedUntil = n;
      return n;
    }
  } catch (eRead) {}
  return 0;
}
function piBookingMarkNetworkBlocked(job) {
  const until = Date.now() + piBookingCooldownMs();
  _piBookingConnectBlockedUntil = Math.max(_piBookingConnectBlockedUntil || 0, until);
  try { require('fs').writeFileSync(PI_BOOKING_BLOCK_FILE, String(_piBookingConnectBlockedUntil)); } catch (eWrite) {}
  if (job) {
    job.networkBlocked = true;
    job.cooldownUntil = _piBookingConnectBlockedUntil;
    job.status = 'blocked';
    job.error = null;
    job.hint = piBookingBlockedHint();
    job.updatedAt = Date.now();
  }
}

